        $tScript = Join-Path $env:TEMP ('dtx-occt-' + [guid]::NewGuid().ToString('N') + '.ps1')
        $cScript = Join-Path $env:TEMP ('dtx-occc-' + [guid]::NewGuid().ToString('N') + '.ps1')
        [void]$occTmp.Add($tScript); [void]$occTmp.Add($cScript)
        $tSrc = @'
