      [System.IO.File]::WriteAllText($gnScript, $gnSrc, (New-Object System.Text.UTF8Encoding($false)))
      [System.IO.File]::WriteAllText($gaScript, $gaSrc, (New-Object System.Text.UTF8Encoding($false)))
